// Synthetic receipt images generated by code (P0-TD-04: "ảnh test sinh bằng
// code (không dùng hóa đơn thật)"; docs/test-strategy.md §1.5).
//
// Produces a deterministic grayscale PNG from a fixture spec: each text line
// becomes a row of blocky pseudo-glyphs derived from the characters, plus a
// seed-dependent header pattern so different specs give different bytes
// (needed for SHA-256 idempotency tests: same image vs different image).
// The picture is not meant to be OCR-readable; FakeAIProvider supplies the
// "recognised" content from the fixture.

import { createHash } from 'node:crypto';
import { deflateSync } from 'node:zlib';
import type { SyntheticImageSpec } from './ai-fixtures';

const PNG_SIGNATURE = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
const GLYPH_W = 4;
const GLYPH_H = 6;
const LINE_H = 10;
const MARGIN = 6;

let crcTable: Uint32Array | undefined;

function getCrcTable(): Uint32Array {
  if (!crcTable) {
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) {
        c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      }
      table[n] = c >>> 0;
    }
    crcTable = table;
  }
  return crcTable;
}

function crc32(data: Buffer): number {
  const table = getCrcTable();
  let crc = 0xffffffff;
  for (const byte of data) {
    crc = table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function chunk(type: string, data: Buffer): Buffer {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const typeAndData = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(typeAndData));
  return Buffer.concat([length, typeAndData, crc]);
}

/** Encode an 8-bit grayscale image (row-major, one byte per pixel). */
export function encodeGrayscalePng(
  width: number,
  height: number,
  pixels: Uint8Array,
): Buffer {
  if (pixels.length !== width * height) {
    throw new Error('pixel buffer size does not match width * height');
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 0; // colour type: grayscale
  ihdr[10] = 0; // compression
  ihdr[11] = 0; // filter
  ihdr[12] = 0; // interlace
  const raw = Buffer.alloc((width + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (width + 1)] = 0; // filter type: none
    raw.set(pixels.subarray(y * width, (y + 1) * width), y * (width + 1) + 1);
  }
  return Buffer.concat([
    PNG_SIGNATURE,
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw)),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

export function renderSyntheticReceipt(spec: SyntheticImageSpec): Buffer {
  const { width, height } = spec;
  const ink = spec.blur ? 170 : 20;
  const pixels = new Uint8Array(width * height).fill(255);
  const plot = (x: number, y: number, value: number) => {
    if (x >= 0 && x < width && y >= 0 && y < height) {
      pixels[y * width + x] = value;
    }
  };

  // Seed header: 2 rows of bits taken from SHA-256(seed).
  const digest = createHash('sha256').update(spec.seed).digest();
  for (let x = 0; x < width; x++) {
    const bit = (digest[(x >> 3) % digest.length] >> (x & 7)) & 1;
    plot(x, 1, bit ? ink : 255);
    plot(x, 2, bit ? ink : 255);
  }

  // Text lines: each character becomes a 4x6 block pattern from its code.
  spec.lines.forEach((line, row) => {
    const top = MARGIN + row * LINE_H;
    [...line].forEach((char, column) => {
      const left = MARGIN + column * (GLYPH_W + 1);
      if (char === ' ') {
        return;
      }
      const code = char.codePointAt(0) ?? 0;
      for (let gy = 0; gy < GLYPH_H; gy++) {
        for (let gx = 0; gx < GLYPH_W; gx++) {
          if ((code >> ((gy * GLYPH_W + gx) % 16)) & 1 || gy === GLYPH_H - 1) {
            plot(left + gx, top + gy, ink);
          }
        }
      }
    });
  });

  return encodeGrayscalePng(width, height, pixels);
}
